def notes_to_comments(apps, schema_editor):
    """Site notes were change-log rows; they become real comments (the log keeps its copy)."""
    Event, Comment = apps.get_model("crm", "LandSiteEvent"), apps.get_model("crm", "Comment")
    for e in Event.objects.filter(kind="note"):
        c = Comment.objects.create(body=e.text, author_id=e.user_id, site_id=e.site_id)
        Comment.objects.filter(pk=c.pk).update(created_at=e.when)
    # The site's creator runs it until someone says otherwise
    Site = apps.get_model("crm", "LandSite")
    for s in Site.objects.filter(owner__isnull=True, created_by__isnull=False):
        s.owner_id = s.created_by_id
        s.save(update_fields=["owner"])


